```swift
enum WorkProblem: Error { case rejected }
actor CompletionLog {
    private var finished = 0
    func item(_ value: Int, fail: Bool) throws -> Int {
        defer { finished += 1 }
        if fail { throw WorkProblem.rejected }
        return value
    }
    func count() -> Int { return finished }
}
func compute(_ log: CompletionLog, fail: Bool) async throws -> Int {
    async let left = log.item(3, fail: fail)
    async let right = log.item(4, fail: false)
    return try await left + right
}
func joined(_ fail: Bool) async -> (value: Int?, completed: Int) {
    let log = CompletionLog()
    do {
        let value = try await compute(log, fail: fail)
        return (value, await log.count())
    } catch {
        return (nil, await log.count())
    }
}
let success = await joined(false)
print(success.value ?? -1)
print(success.completed)
```
Expected output:
```text
7
2
```

